counter = 0

def broken():
    try:
        counter += 1          # assignment makes `counter` local, but it has no value yet
    except UnboundLocalError as error:
        print("UnboundLocalError:", error)

def make_counter():
    count = 0
    def increment():
        nonlocal count        # rebind the enclosing function's variable
        count += 1
        return count
    return increment

broken()
c = make_counter()
print(c(), c(), c())
